mapper.select:
/* selectNoNeSentSmsList */ SELECT TO_CHAR(TO_DATE(SENTTIME, 'YYYYMMDDHH24MISS'), 'YYYY-MM-DD HH24:MI:SS') AS SENTTIME, KEP_WD, CALLPHONE, DECODE(RESULT, '0', '전송대기', 'Y', '전송요청 성공', 'N', '전송요청 실패', '2', '전송성공', '4', '전송실패', '6', '전송결과 미확인') AS RESULT, MSG, DECODE(KIND, 'T', '알림톡', 'S', 'SMS', 'M', 'MMS', 'I', '국제SMS', 'L', '국제MMS') AS KIND FROM SUREDATA_LOG WHERE 1=1 AND KEP_ID = 'GWSMS' AND KEP_WD = #{USER_ID} AND SUBSTR(INTIME, 0, 8) BETWEEN #{st_from_date} AND #{st_to_date}
AND CALLPHONE LIKE '%' || REPLACE(#{st_recv_phone},'-','') || '%'
UNION
SELECT TO_CHAR(TO_DATE(SENTTIME, 'YYYYMMDDHH24MISS'), 'YYYY-MM-DD HH24:MI:SS') AS SENTTIME, KEP_WD, CALLPHONE, DECODE(RESULT, '0', '전송대기', 'Y', '전송요청 성공', 'N', '전송요청 실패', '2', '전송성공', '4', '전송실패', '6', '전송결과 미확인') AS RESULT, MSG, DECODE(KIND, 'T', '알림톡', 'S', 'SMS', 'M', 'MMS', 'I', '국제SMS', 'L', '국제MMS') AS KIND FROM SUREDATA WHERE 1=1 AND KEP_ID = 'GWSMS' AND KEP_WD = #{USER_ID} AND SUBSTR(INTIME, 0, 8) BETWEEN #{st_from_date} AND #{st_to_date}
AND CALLPHONE LIKE '%' || REPLACE(#{st_recv_phone},'-','') || '%'
ORDER BY SENTTIME DESC
